import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as n,af as s}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"The Gemini family","description":"","frontmatter":{},"headers":[],"relativePath":"products/ai-coding/gemini/index.md","filePath":"products/ai-coding/gemini/index.md","lastUpdated":1787044708000}'),o={name:"products/ai-coding/gemini/index.md"};function i(r,e,l,d,h,p){return n(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="the-gemini-family" tabindex="-1">The Gemini family <a class="header-anchor" href="#the-gemini-family" aria-label="Permalink to &quot;The Gemini family&quot;">​</a></h1><blockquote><p>Google&#39;s AI coding and creative product line. This page is the <strong>product map plus a decision tree</strong>: first &quot;what am I trying to do → which product&quot;, then the individual pages.</p><p><strong>Since 2026-06-18</strong>: individual accounts and Google AI Pro / Ultra can no longer use <a href="./gemini-cli.html">Gemini CLI</a> or the <a href="./code-assist.html">Code Assist</a> IDE extensions via <strong>Login with Google</strong>. Move to the <a href="./antigravity.html">Antigravity</a> family. Standard / Enterprise licences and paid API keys are unchanged. Official sources: <a href="https://developers.google.com/gemini-code-assist/docs/deprecations/code-assist-individuals" target="_blank" rel="noreferrer">consumer-account deprecation</a> and the <a href="https://developers.googleblog.com/an-important-update-transitioning-gemini-cli-to-antigravity-cli" target="_blank" rel="noreferrer">transition announcement</a>.</p></blockquote><h2 id="product-map" tabindex="-1">Product map <a class="header-anchor" href="#product-map" aria-label="Permalink to &quot;Product map&quot;">​</a></h2><p>The coding line is split by <strong>who is driving</strong>. Film and prototypes sit where Claude Design sits in that family — they do not compete with the terminal.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Gemini family</span></span>
<span class="line"><span>├── Coding line (who is driving)</span></span>
<span class="line"><span>│   ├── you type, AI completes                         → Code Assist</span></span>
<span class="line"><span>│   ├── you instruct, AI runs it in your terminal      → Gemini CLI</span></span>
<span class="line"><span>│   ├── you set a goal, AI plans and executes          → Antigravity</span></span>
<span class="line"><span>│   └── you hand over a task, AI returns a PR          → Jules</span></span>
<span class="line"><span>├── Prototypes and film (Claude Design counterpart)</span></span>
<span class="line"><span>│   ├── a clickable interactive prototype              → Canvas</span></span>
<span class="line"><span>│   └── landing-page / launch / product-demo video     → Google Flow</span></span>
<span class="line"><span>├── Models and subscription</span></span>
<span class="line"><span>│   ├── tune the model, call the API                   → AI Studio</span></span>
<span class="line"><span>│   └── which tier, how much quota                     → Google AI plans</span></span>
<span class="line"><span>└── Also in Pro, no standalone tutorial</span></span>
<span class="line"><span>    ├── Gemini Spark (US, personal agent)</span></span>
<span class="line"><span>    ├── Gemini Notebook (research / writing)</span></span>
<span class="line"><span>    ├── Gemini app + Deep Research</span></span>
<span class="line"><span>    ├── Gemini in Chrome auto browse (US)</span></span>
<span class="line"><span>    ├── Gemini in Android Studio</span></span>
<span class="line"><span>    └── Google Flow Music (flowmusic.app; credits separate from Flow)</span></span></code></pre></div><p>Dreambeans, Health Premium, Home Premium, TV Create Hub, Earth and Photos Remix travel with the same subscription and are <strong>irrelevant to coding</strong>. This site does not document them. One line lives on the <a href="./google-pro.html#what-else-the-plan-includes">subscription page</a>.</p><h3 id="quick-decision-which-one" tabindex="-1">Quick decision: which one? <a class="header-anchor" href="#quick-decision-which-one" aria-label="Permalink to &quot;Quick decision: which one?&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>What am I trying to do?</span></span>
<span class="line"><span>├── Write / debug / refactor / open a PR</span></span>
<span class="line"><span>│   ├── In the terminal, into a pipe?</span></span>
<span class="line"><span>│   │   ├── personal account → Antigravity CLI</span></span>
<span class="line"><span>│   │   └── Standard / Enterprise or an API key → Gemini CLI</span></span>
<span class="line"><span>│   ├── Cross-module, watch it as it works? → Antigravity</span></span>
<span class="line"><span>│   ├── Clearly bounded, hand it off for a PR? → Jules</span></span>
<span class="line"><span>│   └── Stay in the IDE, or the team has a hard compliance need? → Code Assist</span></span>
<span class="line"><span>├── Interactive prototype / a page you can click</span></span>
<span class="line"><span>│   └── → Canvas</span></span>
<span class="line"><span>│       └── once you pick a direction → Antigravity writes it into the repo</span></span>
<span class="line"><span>├── Landing-page film / product demo / storyboard</span></span>
<span class="line"><span>│   └── → Google Flow</span></span>
<span class="line"><span>│       └── songs / music videos → Flow Music (separate credits; no extra tutorial)</span></span>
<span class="line"><span>├── Temperature, pinned system prompt, large context, API</span></span>
<span class="line"><span>│   └── → AI Studio</span></span>
<span class="line"><span>└── Which tier to buy, is the quota enough</span></span>
<span class="line"><span>    └── → Google AI plans (the table lives only in the cheatsheet)</span></span></code></pre></div><p>The full comparison is in the <a href="./gemini-cheatsheet.html#which-tool">cheatsheet</a>.</p><h2 id="core-products" tabindex="-1">Core products <a class="header-anchor" href="#core-products" aria-label="Permalink to &quot;Core products&quot;">​</a></h2><p>Tutorials stay expanded. The Cookbook sits next to them and stays expanded too.</p><table tabindex="0"><thead><tr><th>Product</th><th>In one line</th><th>When to use it</th></tr></thead><tbody><tr><td><a href="./gemini-cli.html">Gemini CLI</a></td><td>an AI agent in your terminal</td><td>you want AI in pipes and scripts; the family&#39;s conceptual entry point</td></tr><tr><td><a href="./antigravity.html">Antigravity</a></td><td>agent-first development platform</td><td>large cross-module changes you want to verify as they happen</td></tr><tr><td><a href="./jules.html">Jules</a></td><td>asynchronous cloud coding agent</td><td>clearly bounded, time-consuming work you hand off and collect as a PR</td></tr><tr><td><a href="./gemini-cookbook.html">Cookbook</a></td><td>look up a recipe by &quot;what I want to do&quot;</td><td>after the main tutorials, when you start doing the work</td></tr></tbody></table><h2 id="more-products-and-extensions" tabindex="-1">More products and extensions <a class="header-anchor" href="#more-products-and-extensions" aria-label="Permalink to &quot;More products and extensions&quot;">​</a></h2><p>Collapsed by default. Axis A: no prerequisite concepts. Axis B: relevance to frontend engineers — <a href="./flow.html">Flow</a> is the Claude Design counterpart, and sits next to <a href="./canvas.html">Canvas</a>.</p><table tabindex="0"><thead><tr><th>Product</th><th>In one line</th><th>When to use it</th></tr></thead><tbody><tr><td><a href="./canvas.html">Canvas</a></td><td>an interactive workspace beside the conversation</td><td>a clickable prototype, fast</td></tr><tr><td><a href="./flow.html">Google Flow</a></td><td>AI creative studio (Veo 3.1 / Nano Banana / Gemini Omni)</td><td>landing-page, launch and product-demo video</td></tr><tr><td><a href="./code-assist.html">Code Assist</a></td><td>IDE integration</td><td>you do not want to change editor; your team has hard compliance requirements</td></tr><tr><td><a href="./ai-studio.html">AI Studio</a></td><td>model and parameter console</td><td>tuning temperature, pinning a system prompt, large-context audits, API integration</td></tr><tr><td><a href="./google-pro.html">Google AI subscriptions</a></td><td>tiers and quota</td><td>deciding which tier to pay for; drawing Pro entitlements onto the family map</td></tr></tbody></table><h2 id="reference" tabindex="-1">Reference <a class="header-anchor" href="#reference" aria-label="Permalink to &quot;Reference&quot;">​</a></h2><p>Cheatsheet / Glossary stay expanded. Shared tables are written once; other pages only link here.</p><table tabindex="0"><thead><tr><th>Page</th><th>Purpose</th></tr></thead><tbody><tr><td><a href="./gemini-cheatsheet.html">Cheatsheet</a></td><td>decision tables, model status, subscription tiers, configuration paths</td></tr><tr><td><a href="./gemini-glossary.html">Glossary</a></td><td>what Rules / Skill / Subagent / Artifact / Flow actually mean</td></tr></tbody></table><h2 id="suggested-learning-order" tabindex="-1">Suggested learning order <a class="header-anchor" href="#suggested-learning-order" aria-label="Permalink to &quot;Suggested learning order&quot;">​</a></h2><p>The order follows <strong>concept dependency (axis A)</strong> plus <strong>audience complexity (axis B)</strong>. It is not alphabetical and not by popularity:</p><ol><li><strong>Start with <a href="./gemini-cli.html">Gemini CLI</a>.</strong> It is the only complete tool in the family with no prerequisites, and it is where <code>.gemini/settings.json</code>, <code>gemini extensions install</code> and <code>GEMINI.md</code> are first introduced — all three are reused repeatedly later. Individual / Pro / Ultra accounts should do daily work in <a href="./antigravity.html">Antigravity CLI</a>; this page still starts at the CLI because it is the conceptual entry point, not because consumer <strong>Login with Google</strong> still works.</li><li><strong>Then <a href="./antigravity.html">Antigravity</a>.</strong> It reuses those three concepts and adds rules, skills and subagents. After 2026-06-18 this is the daily entry point for individual developers. Skip the CLI and you will get stuck on &quot;what is this configuration file&quot;.</li><li><strong>Then <a href="./jules.html">Jules</a>.</strong> It layers a GitHub repository and PR workflow on top of autonomous agents.</li><li><strong>When you start doing the work, use the <a href="./gemini-cookbook.html">Cookbook</a>.</strong> Look up parameters in the <a href="./gemini-cheatsheet.html">cheatsheet</a>; when two concepts blur, open the <a href="./gemini-glossary.html">glossary</a>.</li><li>After that, read Canvas / Flow / Code Assist / AI Studio / subscription tiers as you need them. They are independent of each other and do not form a chain. Flow has no axis-A prerequisite; on axis B it is mid-to-high relevance for frontend engineers (you will need it when you present a feature), so it belongs in &quot;more products&quot;, not in the core group.</li></ol><p><strong><a href="./code-assist.html">Code Assist</a> comes later not because it is harder</strong>, but because its official positioning targets &quot;organizations with strict data security and compliance requirements&quot;, which is usually not an individual developer&#39;s first need. <strong><a href="./google-pro.html">Subscription tiers</a></strong> come last because they answer &quot;which tier should I pay for&quot;, a question that only makes sense once you know which tool you want.</p><h2 id="quick-decision" tabindex="-1">Quick decision <a class="header-anchor" href="#quick-decision" aria-label="Permalink to &quot;Quick decision&quot;">​</a></h2><table tabindex="0"><thead><tr><th>My situation</th><th>Use</th></tr></thead><tbody><tr><td>Want to try AI coding in the terminal</td><td><a href="./gemini-cli.html">Gemini CLI</a> (enterprise / API key) or <a href="./antigravity.html">Antigravity</a> (individual)</td></tr><tr><td>Have to change something spanning five modules</td><td><a href="./antigravity.html">Antigravity</a></td></tr><tr><td>Have to upgrade React from 18 to 19</td><td><a href="./jules.html">Jules</a></td></tr><tr><td>Do not want to leave VS Code</td><td><a href="./code-assist.html">Code Assist</a></td></tr><tr><td>Want AI to read the whole repository for an audit</td><td><a href="./ai-studio.html">AI Studio</a></td></tr><tr><td>Need to show a product manager a prototype within half an hour</td><td><a href="./canvas.html">Canvas</a></td></tr><tr><td>Need a video for a landing page, launch film or product demo</td><td><a href="./flow.html">Google Flow</a></td></tr><tr><td>Want to know whether the free quota is enough</td><td><a href="./google-pro.html">Subscription tiers</a></td></tr></tbody></table><h2 id="shared-concepts" tabindex="-1">Shared concepts <a class="header-anchor" href="#shared-concepts" aria-label="Permalink to &quot;Shared concepts&quot;">​</a></h2><p>A few things are reused across products. Recognising them up front saves a lot of repeated learning:</p><table tabindex="0"><thead><tr><th>Concept</th><th>Products</th></tr></thead><tbody><tr><td><code>GEMINI.md</code></td><td>Gemini CLI, Antigravity (global rules)</td></tr><tr><td><code>AGENTS.md</code></td><td>Jules</td></tr><tr><td>MCP</td><td>Gemini CLI, Antigravity, Code Assist</td></tr><tr><td>Subscription quota</td><td>one subscription affects the available volume of several products</td></tr><tr><td>Flow credits</td><td><a href="./flow.html">Google Flow</a> only; not the same ledger as Flow Music or Antigravity AI credits</td></tr></tbody></table><p>Exact paths and differences are in the <a href="./gemini-glossary.html">glossary</a> and <a href="./gemini-cheatsheet.html#configuration">configuration in the cheatsheet</a>.</p><h2 id="subscriptions-and-quota" tabindex="-1">Subscriptions and quota <a class="header-anchor" href="#subscriptions-and-quota" aria-label="Permalink to &quot;Subscriptions and quota&quot;">​</a></h2><p>Subscriptions come in four tiers, AI Plus / AI Pro / AI Ultra 5x / AI Ultra 20x — <strong>not two</strong>. Model multipliers, storage and Google Cloud credit per tier are in <a href="./gemini-cheatsheet.html#subscription-tiers">subscription tiers in the cheatsheet</a> and are not duplicated here. Flow&#39;s daily / monthly credits are on <a href="./flow.html#credits">Flow</a>. Coding-relevant Pro entitlements are on the <a href="./google-pro.html">subscription page</a>.</p><h2 id="official-resources" tabindex="-1">Official resources <a class="header-anchor" href="#official-resources" aria-label="Permalink to &quot;Official resources&quot;">​</a></h2><ul><li><a href="https://geminicli.com/docs/" target="_blank" rel="noreferrer">Gemini CLI documentation</a></li><li><a href="https://antigravity.google/docs/home" target="_blank" rel="noreferrer">Antigravity documentation</a></li><li><a href="https://jules.google/docs/" target="_blank" rel="noreferrer">Jules documentation</a></li><li><a href="https://developers.google.com/gemini-code-assist/docs/overview" target="_blank" rel="noreferrer">Code Assist documentation</a></li><li><a href="https://ai.google.dev/gemini-api/docs/models" target="_blank" rel="noreferrer">Gemini API model list</a></li><li><a href="https://labs.google/fx/tools/flow" target="_blank" rel="noreferrer">Google Flow</a></li><li><a href="https://support.google.com/googleone/answer/14534406" target="_blank" rel="noreferrer">Google AI Pro benefits</a></li><li><a href="https://one.google.com/about/google-ai-plans/" target="_blank" rel="noreferrer">Google AI plan comparison</a></li></ul>`,32)])])}const y=t(o,[["render",i]]);export{f as __pageData,y as default};
